import ezdxfdef is_closed_entity(entity):    """    判断实体是否为封闭图形    """    if entity.dxftype() == 'LWPOLYLINE':        return entity.is_closed    elif entity.dxftype() in ['CIRCLE', 'SOLID', 'TRACE', 'SPLINE', 'ELLIPSE', 'POLYLINE']:        # 对于 POLYLINE，检查闭合标志        if entity.dxftype() == 'POLYLINE':            return bool(entity.dxf.flags & 1)  # 1 表示闭合        return True  # 圆、椭圆等默认封闭    return Falsedef split_closed_shapes_to_layers(input_dxf, output_dxf):    try:        doc = ezdxf.readfile(input_dxf)    except IOError:        print(f"无法读取文件: {input_dxf}")        return    except ezdxf.DXFStructureError:        print(f"DXF 结构错误，文件可能不是有效的 DXF: {input_dxf}")        return    modelspace = doc.modelspace()    # 过滤出所有封闭图形实体    closed_entities = [e for e in modelspace if is_closed_entity(e)]    print(f"找到 {len(closed_entities)} 个封闭图形。")    # 为每个封闭图形分配独立图层    for idx, entity in enumerate(closed_entities, start=1):        layer_name = str(idx)        # 如果图层不存在，创建它        if layer_name not in doc.layers:            doc.layers.new(name=layer_name)        # 修改实体图层        entity.dxf.layer = layer_name    # 保存新文件    doc.saveas(output_dxf)    print(f"处理完成！已保存为: {output_dxf}")# 使用示例if __name__ == "__main__":    input_file = "C:/Users/qjq/Desktop/imagekj/SF5D.dxf"        # 请先将 SF5D.dwg 转为 SF5D.dxf    output_file = "C:/Users/qjq/Desktop/imagekj/stonegeomerty/SF5.dxf" # 输出文件    split_closed_shapes_to_layers(input_file, output_file)